vec3 getCustomColor(vec2 in_uv) {
    vec2 q = in_uv * 6.2831;
    float val = sin(q.x + iTime) + sin(q.y + iTime) + sin(q.x + q.y + iTime);
    float c = 0.5 + 0.5 * sin(val);
    return mix(u_col1, u_col2, c);
}

